#!/bin/bash
# DRAM-access accounting (ftlsim dram_stats=1; Part C2). Same workload/geometry arguments as tools/sens.py baseline
# (OP 7%, 18.75% DRAM, 1 MiB buffer). Trace reads (and one read probe per write request for synthetic zipf) go
# through each policy's lookup. ali1 uses ali1r.csv = ali1.csv regenerated by trace_prep with reads=1 (same writes).
#   SIM=<ftlsim built with dram_stats> tools/run_dram_stats.sh [workload ...]
cd "$(dirname "$0")/.."
SIM=${SIM:-./ftlsim/ftlsim}; OUT=${OUT:-results/sens_dram}; CPUS=${CPUS:-0-92:2}
for wl in ${@:-z0.99 ycsbb_d_t64 ali1}; do
  python3 - "$wl" <<'PY'
import sys
sys.path.insert(0, 'tools')
import sens
wl = sys.argv[1]
src = 'ali1' if wl == 'ali1' else wl
for pol, kw in (('prop', {}), ('page4k', {}), ('dftl', {}), ('leaftl', {}), ('iu_rmw', {}), ('prop', {'U': 32}), ('prop', {'U': 8})):
    w, tag, args = sens.job(src, pol, **kw)
    if wl == 'ali1':
        args = args.replace('/home/sejun000/traces_dm/ali1.csv', '/mnt/nvme_mounted/dm_c2/ali1r.csv')
    print(wl, tag, args)
PY
done | while read wl tag args; do
  mkdir -p $OUT/$wl
  echo "$OUT/$wl $tag $args dram_stats=1"
done | xargs -P ${JOBS:-12} -L 1 bash -c 'o=$0; t=$1; shift 1; /usr/bin/time -f "%e s %M KB" -o $o/$t.time taskset -c '"$CPUS"' '"$SIM"' "$@" tag=$t > $o/$t.json 2> $o/$t.log'
